// 2025-1-11 20:53
// 高维投影，彭罗斯镶嵌，准周期，拟周期
// https://www.shadertoy.com/view/XccXW8



int N=7;// ; // 维度  N==0 Auto


const int AC = 12;
float U[AC], V[AC],p[AC],A[AC], B[AC];
//vec2 pro[AC];

vec2 fA, fB;



void init()
{
        float fN = float(N);
        float k = sqrt( 2. / fN ); // 单位长度因子
        for(int i = 0;i < N; i++)
        {
                U[i] = cos(radians(360./fN/2. * float(i))) * k;
                V[i] = sin(radians(360./fN/2. * float(i))) * k;
                A[i]=0.;
                B[i]=0.;
        }
}

float dotN(float a[AC], float b[AC])
{
        float s = 0.;
        for(int i=0; i<N; i++)
        {
                s += a[i] * b[i];
        }
        return s;
}

vec2 proj(float p[AC])
{
        return vec2(dotN(p, U), dotN(p, V));
}



float tile(mat2 m, vec2 s)
{
        float e[AC];
        vec2 q = s * m ;


        for(int i=0; i<N; i++)
        {
                e[i] = p[i] - (1.-A[i]-B[i])*round(dot(q,vec2(U[i],V[i])));//q.x * U[i] + q.y * V[i]);
        }

        vec2 f = .5 - abs(m * proj(e) -s);
        return max(0., min(f.x, f.y));
}


float faceAB()
{

        mat2 m = inverse(mat2(proj(A), proj(B)));


        vec2 r = round(vec2(dotN(p,A), dotN(p,B)));
        vec2 s = vec2(.5, -.5);
        float d = tile(m, r+s.xx) + tile(m, r+s.xy) + tile(m, r+s.yx) + tile(m, r+s.yy);
        //return d;

        float lw = .04;  // line width
        float aa = 0.01;  // antialiasing width (depends on resolution and zoom)

        return d + smoothstep(lw-aa, lw+aa,
                   min(d / length(vec2(m[0].x, m[1].x)),
                       d / length(vec2(m[0].y, m[1].y))));
}


float dim(vec2 u)
{
        init();
        float c = 0.;
        for(int i=0; i < N; i++)
        {
                p[i] = u.x * U[i] + u.y * V[i];
        }



        for(int j =0; j< N-1;j++)
        {
                A[j]=1.;
                for(int i =j+1; i< N;i++)
                {
                        B[i]=1.;
                        c += faceAB(); // p , a, b
                        B[i]=0.;
                }      
                A[j]=0.;
        }
        return c;
}




void mainImage( out vec4 O, vec2 U )
{

        vec2 R = iResolution.xy, 
             u = 5.*(U+U - R) / R.y + iTime;
        if(N==0)N = int(iTime) % AC+3;   ;// int(iMouse.x/R.x*float(Lth-3))% (Lth-3)+3; // iTime 对速度影响较大
        if(N>=AC)N=AC-1;
        O = vec4( pow(dim(u),.25) );

}
